"""Composite admin handlers for the modular admin panel."""

from typing import Sequence

from core.context import CustomContext
from telegram import Update
from telegram.ext import ConversationHandler
from utils.subscribers_pg import SubscribersPostgres as Subscribers
from handlers.admin.modules.base_handler import BaseAdminHandler
from handlers.admin.admin_handler_setup import (
    init_action_routes,
    init_attachment_handlers,
    init_content_handlers,
    init_new_feature_handlers,
    init_support_handlers,
    init_system_handlers,
)
from handlers.admin.admin_entry_flow import (
    run_admin_cancel,
    run_admin_exit_silent,
    run_admin_start,
    run_admin_start_msg,
    run_search_cancel_and_admin,
)
from handlers.admin.navigation_routing import handle_admin_navigation_back
from utils.logger import get_logger, log_admin_action
from utils.language import get_user_lang
from utils.i18n import t

logger = get_logger("admin_modular", "admin.log")


class AdminHandlers(BaseAdminHandler):
    """AdminHandlers Composite Class"""

    def __init__(self, db, container=None, role_manager=None, audit_logger=None):
        super().__init__(
            db,
            container=container,
            role_manager=role_manager,
            audit_logger=audit_logger,
        )
        self.subs = Subscribers(db_adapter=db)
        from managers.notification_manager import NotificationManager

        self.notif_manager = NotificationManager(db, self.subs)
        self._init_attachment_handlers()
        self._init_system_handlers()
        self._init_support_handlers()
        self._init_content_handlers()
        self._init_new_feature_handlers()
        self._init_action_routes()

    def _bind_handler_methods(self, handler, method_names: Sequence[str]) -> None:
        for method_name in method_names:
            setattr(self, method_name, getattr(handler, method_name))

    def _init_attachment_handlers(self):
        init_attachment_handlers(self)

    def _init_system_handlers(self):
        init_system_handlers(self)

    def _init_support_handlers(self):
        init_support_handlers(self)

    def _init_content_handlers(self):
        init_content_handlers(self)

    def _init_new_feature_handlers(self):
        init_new_feature_handlers(self)

    def _init_action_routes(self) -> None:
        init_action_routes(self)

    async def _admin_menu_noop(self, update: Update, context: CustomContext):
        del context
        query = update.callback_query
        if query:
            await query.answer()
        from handlers.admin.admin_states import ADMIN_MENU

        return ADMIN_MENU

    async def _admin_menu_exit(self, update: Update, context: CustomContext):
        lang = await get_user_lang(update, context, self.db) or "fa"
        query = update.callback_query
        if query:
            await query.edit_message_text(t("admin.exit.done", lang))
        return ConversationHandler.END

    async def admin_start(self, update: Update, context: CustomContext):
        return await run_admin_start(self, update, context)

    @log_admin_action("admin_start_msg")
    async def admin_start_msg(self, update: Update, context: CustomContext):
        return await run_admin_start_msg(self, update, context)

    @log_admin_action("admin_menu")
    async def admin_menu(self, update: Update, context: CustomContext):
        """Admin menu routing for modular handlers."""
        from handlers.admin.admin_states import ADMIN_MENU

        query = update.callback_query
        logger.info(f"admin_menu called with callback: {query.data}")

        user_id = query.from_user.id
        lang = await get_user_lang(update, context, self.db) or "fa"
        if not await self.is_admin(user_id):
            await self.audit_permission_denied(
                user_id,
                route="admin_menu",
                permission="ADMIN_ACCESS",
                source="admin_menu",
            )
            await query.answer()
            await query.edit_message_text(t("admin.not_admin", lang))
            return ConversationHandler.END

        if "admin_entry_handled" not in context.user_data:
            self._clear_navigation(context)
            context.user_data["admin_entry_handled"] = True

        action = query.data

        exact_handler = self._admin_menu_exact_routes.get(action)
        if exact_handler is not None:
            return await exact_handler(update, context)

        for router, routes in self._admin_menu_route_groups:
            route_result = await router(action, update, context, routes)
            if route_result is not None:
                return route_result

        logger.warning(f"Unhandled action in admin_menu: {action}")
        return ADMIN_MENU

    async def admin_cancel(self, update: Update, context: CustomContext):
        return await run_admin_cancel(self, update, context)

    async def search_cancel_and_admin(self, update: Update, context: CustomContext):
        return await run_search_cancel_and_admin(self, update, context)

    async def admin_exit_silent(self, update: Update, context: CustomContext):
        return await run_admin_exit_silent(self, update, context)

